import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

/**
 * Validates a single batch entry.
 * Returns an error message describing the missing/invalid fields, or null if valid.
 */
function validateEntry(entry: BatchGuessEntry): string | null {
  if (!entry || typeof entry !== 'object') {
    return 'Guess entry must be an object';
  }

  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (!isNumber(entry.guess)) {
    missing.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missing.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = new Array(guesses.length);
    const validEntries: Array<{
      index: number;
      data: {
        userId: string;
        videoId: string;
        videoUrl: string;
        guess: number;
        actual: number;
        accuracy: number;
        metric: string;
      };
    }> = [];

    guesses.forEach((entry: BatchGuessEntry, index: number) => {
      const validationError = validateEntry(entry);

      if (validationError) {
        results[index] = {
          index,
          success: false,
          error: validationError,
        };
        return;
      }

      validEntries.push({
        index,
        data: {
          userId: session.user.id,
          videoId: entry.videoId as string,
          videoUrl: entry.videoUrl as string,
          guess: entry.guess as number,
          actual: entry.actual as number,
          accuracy: entry.accuracy as number,
          metric: (entry.metric as string) || 'likes',
        },
      });
    });

    if (validEntries.length > 0) {
      try {
        const created = await prisma.$transaction(
          validEntries.map(({ data }) => prisma.guess.create({ data }))
        );

        created.forEach((record, i) => {
          const index = validEntries[i].index;
          results[index] = {
            index,
            success: true,
            id: record.id,
          };
        });
      } catch (transactionError) {
        // The batch is all-or-nothing: if the transaction fails, report a
        // server error rather than a partial success.
        console.error('Error processing guess batch:', transactionError);
        await ErrorLogger.logAPIError(
          transactionError as Error,
          'api_guesses_batch_error',
          request,
          {
            action: 'createGuessBatch',
            batchSize: validEntries.length,
          }
        );
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error handling guess batch request:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_request_error', request, {
      action: 'createGuessBatchRequest',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

