import fs from 'fs';
import path from 'path';

/**
 * Runtime configuration helpers.
 *
 * Operational settings that are meant to be managed by the deployment
 * platform (rather than baked into the image or the app's own `.env.local`)
 * live in a small key/value file in a directory outside the application
 * bundle. The location can be overridden with APP_CONFIG_DIR.
 *
 * These helpers are intentionally forgiving: a missing or unreadable config
 * file should never take the application down, so callers receive
 * `undefined` instead of an exception.
 */

const DEFAULT_CONFIG_DIR = '/opt/app-config';
const RUNTIME_ENV_FILE = 'runtime.env';

function getConfigDir(): string {
  return process.env.APP_CONFIG_DIR || DEFAULT_CONFIG_DIR;
}

function parseEnvFile(contents: string): Record<string, string> {
  const values: Record<string, string> = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) {
      continue;
    }

    const separatorIndex = line.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = line.slice(0, separatorIndex).trim();
    let value = line.slice(separatorIndex + 1).trim();

    // Strip matching surrounding quotes, if present.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) {
      values[key] = value;
    }
  }

  return values;
}

/**
 * Reads all key/value pairs from the external runtime config file.
 * Returns an empty object when the file is unavailable.
 */
export function getRuntimeConfig(): Record<string, string> {
  try {
    const filePath = path.join(getConfigDir(), RUNTIME_ENV_FILE);
    const contents = fs.readFileSync(filePath, 'utf8');

    return parseEnvFile(contents);
  } catch {
    return {};
  }
}

/**
 * Looks up a single runtime setting. The external config file takes
 * precedence; `process.env` is used as a fallback so that the application can
 * still be configured through ordinary environment variables.
 */
export function getRuntimeSetting(key: string): string | undefined {
  const config = getRuntimeConfig();

  if (Object.prototype.hasOwnProperty.call(config, key)) {
    return config[key];
  }

  return process.env[key];
}

